# Perform BFS from start_node to find nodes at exactly depth 6
from collections import deque

def bfs_at_depth(graph, start, target_depth):
    # BFS to find nodes at exactly target_depth
    # Returns nodes at exactly that depth (not including start or intermediate depths)

    if target_depth == 0:
        return []  # Don't return start node

    visited = set([start])
    queue = deque([(start, 0)])  # (node, depth)
    result = []

    while queue:
        node, depth = queue.popleft()

        if depth == target_depth:
            result.append(node)
            continue  # Don't explore further from target depth

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, depth + 1))

    return result

# Find nodes at depth 6
nodes_at_depth_6 = bfs_at_depth(graph, start_node, 6)
print(f"Nodes at depth 6: {nodes_at_depth_6}")
print(f"Count: {len(nodes_at_depth_6)}")

# Let's also trace the BFS levels to verify
def trace_bfs(graph, start, max_depth):
    visited = set([start])
    queue = deque([(start, 0)])
    levels = {0: [start]}

    while queue:
        node, depth = queue.popleft()
        if depth >= max_depth:
            continue

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, depth + 1))
                if depth + 1 not in levels:
                    levels[depth + 1] = []
                levels[depth + 1].append(neighbor)

    return levels

levels = trace_bfs(graph, start_node, 6)
for d in range(7):
